    public void member(ServerPlayer player,UUID who)throws Exception {
        core.check(player,"settings");Team team=core.requireTeam(player);Member target=core.store.member(who).orElseThrow(()->new TeamsCore.Refusal("NO_MEMBER"));if(target.teamId()!=team.id())throw new TeamsCore.Refusal("STALE_GUI");
        Member actor=core.requireMember(player);if(!who.equals(player.getUUID())&&!actor.owner()&&!(actor.role().equals("CO_OWNER")&&target.role().equals("MEMBER")))throw new TeamsCore.Refusal("DENIED");
        Screen menu=new Screen(player,"member-edit-gui",54,"Member: "+core.playerName(who));
        menu.context.put("player_name",core.playerName(who));menu.context.put("role",target.role());menu.context.put("joindate",Objects.toString(target.field("join_date"),""));
        menu.context.put("target_name",core.playerName(who));menu.context.put("role_icon",core.settings.placeholder("roles."+target.role().toLowerCase(Locale.ROOT)+".icon",""));menu.context.put("platform_indicator",core.platform(who));String enabled=core.settings.message("status_enabled","<green>ENABLED"),disabled=core.settings.message("status_disabled","<red>DISABLED");menu.context.put("withdraw_status",target.flag("can_withdraw")?enabled:disabled);menu.context.put("enderchest_status",target.flag("can_use_enderchest")?enabled:disabled);menu.context.put("set_home_status",target.flag("can_set_home")?enabled:disabled);menu.context.put("use_home_status",target.flag("can_use_home")?enabled:disabled);menu.context.put("promote_co_owner_status",target.flag("can_promote_to_co_owner")?enabled:disabled);
        menu.button("player-info-head",4,"PLAYER_HEAD","<player_name>",null);int headSlot=number("member-edit-gui.items.player-info-head.slot",4);if(headSlot>=0&&headSlot<menu.inventory.getContainerSize())menu.inventory.getItem(headSlot).set(DataComponents.PROFILE,new ResolvableProfile(new com.mojang.authlib.GameProfile(who,core.playerName(who))));
        if(!who.equals(player.getUUID())&&!target.owner()){menu.button(target.role().equals("CO_OWNER")?"demote-button":"promote-button",19,"LIME_DYE","&aPromote / Demote",p->{Member fresh=core.store.member(who).orElseThrow();core.role(p,who,!fresh.role().equals("CO_OWNER"));member(p,who);});menu.button("kick-button",22,"BARRIER","&cKick",p->confirm(p,"Kick",()->core.kick(p,who)));if(actor.owner())menu.button("transfer-button",25,"NETHER_STAR","&eTransfer owner",p->confirm(p,"Transfer",()->core.transfer(p,who)));}
        String[] flags={"can_promote_to_co_owner","can_withdraw","can_use_enderchest","can_set_home","can_use_home"};int[] slots={28,37,39,41,43};String[] keys={"toggle-promote-co-owner","withdraw-permission","enderchest-permission","sethome-permission","usehome-permission"};
        for(int i=0;i<flags.length;i++){if(i==0&&(!target.role().equals("CO_OWNER")||!team.owner().equals(player.getUUID())||who.equals(player.getUUID())))continue;String flag=flags[i];menu.context.put("status",Boolean.toString(target.flag(flag)));menu.context.put("flag",Boolean.toString(target.flag(flag)));menu.context.put("status_text",target.flag(flag)?"Enabled":"Disabled");boolean self=who.equals(player.getUUID());menu.button(keys[i]+(self?"-view":""),slots[i],"LEVER","&e"+flag+": "+target.flag(flag),self?null:p->{Member fresh=core.store.member(who).orElseThrow();core.editFlag(p,who,flag,!fresh.flag(flag));member(p,who);});}back(menu,49);menu.open();
    }
