    public void admin(ServerPlayer player,int page)throws Exception{core.requireAdmin(player);Screen menu=new Screen(player,"admin-gui",54,"justTeams Admin");List<Map<String,Object>> teams=core.store.rows("teams",null,null);int start=Math.max(0,page)*36;for(int i=0;i<36&&start+i<teams.size();i++){int id=((Number)teams.get(start+i).get("id")).intValue();Team team=core.store.team(id).orElseThrow();menu.direct(9+i,"PLAYER_HEAD",team.name(),List.of("Members "+core.store.members(id).size(),"Bank "+Texts.money(team.balance())),p->adminTeam(p,id,0));}if(page>0)menu.direct(48,"ARROW","Previous",List.of(),p->admin(p,page-1));if(start+36<teams.size())menu.direct(50,"ARROW","Next",List.of(),p->admin(p,page+1));menu.direct(53,"BARRIER","Close",List.of(),ServerPlayer::closeContainer);menu.open();}
    public void adminTeam(ServerPlayer player,int id,int page)throws Exception{core.requireAdmin(player);Team team=core.store.team(id).orElseThrow(()->new TeamsCore.Refusal("UNKNOWN_TEAM"));Screen menu=new Screen(player,"admin-team-manage-gui",54,"Admin: "+team.name());
        menu.direct(11,"GOLD_INGOT","Edit bank balance",List.of(Texts.money(team.balance())),p->{core.requireAdmin(p);String op=UUID.randomUUID().toString();core.prompt(p,"Bank balance",text->core.safely(p,()->{core.adminBalance(p,id,Double.parseDouble(text),op);adminTeam(p,id,page);}));});
        menu.direct(1,"WRITABLE_BOOK","Edit description",List.of(),p->adminText(p,id,"description"));menu.direct(2,"NAME_TAG","Rename team",List.of(),p->adminText(p,id,"name"));menu.direct(3,"NAME_TAG","Edit tag",List.of(),p->adminText(p,id,"tag"));menu.direct(9,"OAK_DOOR","Public: "+team.isPublic(),List.of(),p->{core.adminSetting(p,id,"is_public",!core.store.team(id).orElseThrow().isPublic());adminTeam(p,id,page);});menu.direct(10,"DIAMOND_SWORD","PvP: "+team.pvp(),List.of(),p->{core.adminSetting(p,id,"pvp_enabled",!core.store.team(id).orElseThrow().pvp());adminTeam(p,id,page);});
menu.direct(12,"DIAMOND_SWORD","Edit kills / deaths",List.of(),p->core.prompt(p,"Kills deaths",text->core.safely(p,()->{String[] fields=text.strip().split("\\s+");if(fields.length!=2)throw new TeamsCore.Refusal("INVALID_STAT");int kills=Integer.parseInt(fields[0]),deaths=Integer.parseInt(fields[1]);if(kills<0||deaths<0)throw new TeamsCore.Refusal("INVALID_STAT");core.adminStats(p,id,kills,deaths);adminTeam(p,id,page);})));menu.direct(13,"ENDER_CHEST","Team chest",List.of(),p->core.chests.openAdministrative(p,core.store.team(id).orElseThrow()));menu.direct(14,"ENDER_PEARL","Team home",List.of(),p->core.adminHome(p,id));menu.direct(17,"BARRIER","Disband",List.of(),p->confirm(p,"Admin disband",()->{core.adminDisband(p,id);admin(p,0);}));
        List<Member> members=core.store.members(id);int start=Math.max(0,page)*27;for(int i=0;i<27&&start+i<members.size();i++){Member member=members.get(start+i);menu.direct(18+i,"PLAYER_HEAD",Objects.toString(member.name(),member.uuid().toString()),List.of(member.role()),p->adminMember(p,member.uuid()));}menu.direct(45,"ARROW","Back",List.of(),p->admin(p,0));if(page>0)menu.direct(48,"ARROW","Previous members",List.of(),p->adminTeam(p,id,page-1));if(start+27<members.size())menu.direct(50,"ARROW","Next members",List.of(),p->adminTeam(p,id,page+1));menu.direct(53,"CLOCK","Refresh",List.of(),p->adminTeam(p,id,page));menu.open();}
    private void adminText(ServerPlayer player,int id,String field){core.requireAdmin(player);core.prompt(player,field,text->core.safely(player,()->{core.adminSetting(player,id,field,text);adminTeam(player,id,0);}));}
    public void adminMember(ServerPlayer player,UUID target)throws Exception{core.requireAdmin(player);Member member=core.store.member(target).orElseThrow(()->new TeamsCore.Refusal("NO_MEMBER"));Screen menu=new Screen(player,"admin-member-edit-gui",54,"Admin member: "+core.playerName(target));String[] flags={"can_withdraw","can_use_enderchest","can_set_home","can_use_home","can_promote_to_co_owner"};for(int i=0;i<flags.length;i++){if(i==4&&!member.role().equals("CO_OWNER"))continue;String flag=flags[i];menu.direct(19+i,"LEVER",flag+": "+member.flag(flag),List.of(),p->{core.adminMember(p,target,flag);adminMember(p,target);});}if(!member.owner()){menu.direct(29,"LIME_DYE","Promote",List.of(),p->{core.adminMember(p,target,"promote");adminMember(p,target);});menu.direct(30,"RED_DYE","Demote",List.of(),p->{core.adminMember(p,target,"demote");adminMember(p,target);});menu.direct(33,"BARRIER","Kick",List.of(),p->confirm(p,"Admin kick",()->{core.adminMember(p,target,"kick");adminTeam(p,member.teamId(),0);}));}menu.direct(45,"ARROW","Back",List.of(),p->adminTeam(p,member.teamId(),0));menu.open();}
    private boolean questEnabled(){Object root=core.settings.quests().get("settings");return root instanceof Map<?,?> values&&Boolean.TRUE.equals(values.get("enabled"));}
    private int memberSort(int team)throws Exception{for(var row:core.store.rows("team_custom_data","team_id",team))if("member_sort_type".equals(row.get("data_key")))return switch(Objects.toString(row.get("data_value"),"")){case "ALPHABETICAL"->1;case "ONLINE_STATUS"->2;default->0;};return 0;}
    private void back(Screen screen,int slot)throws Exception{screen.button("back-button",slot,"ARROW","&7Back",this::team);}
    private Component render(ServerPlayer player,String text,Map<String,String> context)throws Exception {
        var snapshot=core.snapshots.subject(player.getUUID());Team team=snapshot.team();Map<String,String> values=new LinkedHashMap<>(),trusted=new LinkedHashMap<>();values.put("player",player.getGameProfile().getName());values.put("player_name",player.getGameProfile().getName());
        if(team!=null){values.put("team_name",team.name());trusted.put("team_tag",Texts.tagMarkup(team.tag()));values.put("team_description",Objects.toString(team.field("description"),""));values.put("members",Integer.toString(snapshot.members().size()));values.put("max_members",Integer.toString(core.capacity(team)));values.put("team_balance",Texts.money(team.balance()));values.put("balance",Texts.money(team.balance()));values.put("tier",Integer.toString(team.tier()));values.put("public_status",Boolean.toString(team.isPublic()));}
        values.putAll(context);for(String key:List.of("status","status_text","public_status","permission_prompt","role_icon","status_indicator","withdraw_status","enderchest_status","set_home_status","use_home_status","promote_co_owner_status","sort_status_join_date","sort_status_alphabetical","sort_status_online_status"))if(values.containsKey(key))trusted.put(key,values.remove(key));return Texts.template(text,values,trusted);
    }
    private Object value(String path){Object current=core.settings.gui();for(String part:path.split("\\.")){if(!(current instanceof Map<?,?> map))return null;current=map.get(part);}return current;}
    private String string(String path,String fallback){Object result=value(path);return result==null?fallback:result.toString();}
    private int number(String path,int fallback){Object result=value(path);return result instanceof Number number?number.intValue():fallback;}
    private boolean bool(String path,boolean fallback){Object result=value(path);return result instanceof Boolean bool?bool:fallback;}
    private static ItemStack item(String material,String name,List<String> lore){ResourceLocation key=ResourceLocation.tryParse(material.toLowerCase(Locale.ROOT));Item type=key!=null?BuiltInRegistries.ITEM.get(key):Items.BARRIER;if(type==Items.AIR)type=Items.BARRIER;ItemStack stack=new ItemStack(type);stack.set(DataComponents.CUSTOM_NAME,Texts.of(name).copy().withStyle(style->style.withItalic(false)));if(!lore.isEmpty())stack.set(DataComponents.LORE,new ItemLore(lore.stream().map(line->Texts.of(line).copy().withStyle(style->style.withItalic(false))).<Component>map(component->component).toList()));return stack;}
    private static ItemStack item(String material,Component name,List<Component> lore){ResourceLocation key=ResourceLocation.tryParse(material.toLowerCase(Locale.ROOT));Item type=key!=null?BuiltInRegistries.ITEM.get(key):Items.BARRIER;if(type==Items.AIR)type=Items.BARRIER;ItemStack stack=new ItemStack(type);stack.set(DataComponents.CUSTOM_NAME,name.copy().withStyle(style->style.withItalic(false)));if(!lore.isEmpty())stack.set(DataComponents.LORE,new ItemLore(lore.stream().map(line->line.copy().withStyle(style->style.withItalic(false))).<Component>map(component->component).toList()));return stack;}
    private static MenuType<?> type(int rows){return switch(rows){case 1->MenuType.GENERIC_9x1;case 2->MenuType.GENERIC_9x2;case 3->MenuType.GENERIC_9x3;case 4->MenuType.GENERIC_9x4;case 5->MenuType.GENERIC_9x5;default->MenuType.GENERIC_9x6;};}
